import sys
import math

eps = 1e-6
PI = math.acos(-1.0)

class Point:
    __slots__ = ('x', 'y')
    def __init__(self, x=0.0, y=0.0):
        self.x = x
        self.y = y

    def set(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Point(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Point(self.x - other.x, self.y - other.y)

    def __mul__(self, k):
        return Point(self.x * k, self.y * k)

    def __truediv__(self, k):
        return Point(self.x / k, self.y / k)

    def __rmul__(self, k):
        return self * k

    def rot90(self):
        return Point(-self.y, self.x)

    def __repr__(self):
        return f"({self.x:.6f}, {self.y:.6f})"

def dMult(a, b):
    return a.x * b.x + a.y * b.y

def xMult(a, b):
    return a.x * b.y - a.y * b.x

def VecMod(a):
    return math.hypot(a.x, a.y)

def VecMod2(a):
    return dMult(a, a)

def VecUnit(a):
    mod = VecMod(a)
    if mod < eps:
        return Point(0, 0)
    return a / mod

def VRotate(v, alph):
    sa = math.sin(alph)
    ca = math.cos(alph)
    return Point(v.x * ca - v.y * sa, v.x * sa + v.y * ca)

def PRotate(p, o, alph):
    return o + VRotate(p - o, alph)

def ShadowPOnLine(p, a, b):
    ab = b - a
    ap = p - a
    if VecMod2(ab) < eps:
        return a
    alph = VecUnit(ab) * (dMult(ab, ap) / VecMod(ab))
    return a + alph

def LineCrossCircle(a, b, o, r):
    ret = []
    t = ShadowPOnLine(o, a, b)
    ot = t - o
    d = VecMod(ot)
    if d - r > eps:
        return ret
    if abs(d - r) < eps:
        ret.append(t)
        return ret
    lr = math.sqrt(max(0.0, r * r - VecMod2(ot)))
    dir_vec = VecUnit(a - b) if VecMod(a - b) > eps else Point(0, 0)
    ta = t + dir_vec * lr
    tb = t - dir_vec * lr
    ret.append(ta)
    ret.append(tb)
    return ret

def PointTangentCircle(p, o, r):
    ret = []
    po = p - o
    x2 = VecMod2(po)
    d2 = x2 - r * r
    if d2 < -eps:
        return ret
    if r <= eps:
        ret.append(o)
        ret.append(o)
        return ret
    d2 = max(0.0, d2)
    q1 = o + po * (r * r / x2)
    q2 = po.rot90() * (-r * math.sqrt(d2) / x2)
    ret.append(q1 - q2)
    ret.append(q1 + q2)
    return ret

def POnSeg(p, a, b):
    if abs(xMult(b - a, p - a)) > eps:
        return False
    if min(a.x, b.x) - eps > p.x or p.x > max(a.x, b.x) + eps:
        return False
    if min(a.y, b.y) - eps > p.y or p.y > max(a.y, b.y) + eps:
        return False
    return True

def PDisLine(p, a, b):
    return VecMod(ShadowPOnLine(p, a, b) - p)

def Corner2V(a, b):
    mod_a = VecMod(a)
    mod_b = VecMod(b)
    if mod_a < eps or mod_b < eps:
        return 0.0
    cos_val = dMult(a, b) / mod_a / mod_b
    cos_val = max(-1.0, min(1.0, cos_val))
    return abs(math.acos(cos_val))

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    out_lines = []
    while True:
        try:
            px = float(next(it))
            py = float(next(it))
            vp = float(next(it))
            sx = float(next(it))
            sy = float(next(it))
            vs = float(next(it))
            r = float(next(it))
        except StopIteration:
            break

        p = Point(px, py)
        s = Point(sx, sy)

        len_or = VecMod(p)
        if len_or < eps:
            sita = 0.0
        else:
            sita = math.acos(max(-1.0, min(1.0, p.x / len_or)))
            if p.y < 0:
                sita = -sita

        def check(t):
            angle = sita + t * vp / len_or if len_or > eps else sita
            e = Point(len_or * math.cos(angle), len_or * math.sin(angle))

            ccp = LineCrossCircle(s, e, Point(0, 0), r)
            if len(ccp) != 2 or (not POnSeg(ccp[0], s, e) and not POnSeg(ccp[1], s, e)):
                return vs * t > VecMod(e - s) - eps

            ttp1 = PointTangentCircle(s, Point(0, 0), r)
            if len(ttp1) < 2:
                return vs * t > VecMod(e - s) - eps
            if PDisLine(ttp1[0], s, e) > PDisLine(ttp1[1], s, e):
                ttp1[0], ttp1[1] = ttp1[1], ttp1[0]
            l1 = VecMod(ttp1[0] - s)

            ttp2 = PointTangentCircle(e, Point(0, 0), r)
            if len(ttp2) < 2:
                return vs * t > VecMod(e - s) - eps
            if PDisLine(ttp2[0], s, e) > PDisLine(ttp2[1], s, e):
                ttp2[0], ttp2[1] = ttp2[1], ttp2[0]
            l2 = VecMod(ttp2[0] - e)

            alph = Corner2V(ttp1[0], ttp2[0])
            return l1 + l2 + alph * r < vs * t + eps

        left = 0.0
        right = 1e10
        for _ in range(100):
            mid = (left + right) * 0.5
            if check(mid):
                right = mid
            else:
                left = mid
        out_lines.append(f"{left:.9f}")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

