import math
import sys

eps = 1e-9
pi = math.acos(-1.0)

class Point:
    __slots__ = ('x', 'y')
    def __init__(self, x=0.0, y=0.0):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Point(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Point(self.x - other.x, self.y - other.y)

    def __mul__(self, k):
        return Point(self.x * k, self.y * k)

    def __truediv__(self, k):
        return Point(self.x / k, self.y / k)

    def __repr__(self):
        return f"({self.x:.6f}, {self.y:.6f})"

    def rot90(self):
        return Point(-self.y, self.x)

    def set(self, x, y):
        self.x = x
        self.y = y

def dot(a, b):
    return a.x * b.x + a.y * b.y

def cross(a, b):
    return a.x * b.y - a.y * b.x

def mod(a):
    return math.hypot(a.x, a.y)

def mod2(a):
    return dot(a, a)

def unit(a):
    m = mod(a)
    if m < eps: return Point(0, 0)
    return a / m

def rotate(v, alpha):
    sa = math.sin(alpha)
    ca = math.cos(alpha)
    return Point(v.x * ca - v.y * sa, v.x * sa + v.y * ca)

def angle_between(a, b):
    # returns absolute angle in radians
    m1 = mod(a)
    m2 = mod(b)
    if m1 < eps or m2 < eps: return 0.0
    cos_val = dot(a, b) / (m1 * m2)
    cos_val = max(-1.0, min(1.0, cos_val))
    return math.acos(cos_val)

def project_on_line(p, a, b):
    # foot of perpendicular from p to line ab
    ab = b - a
    ap = p - a
    if mod2(ab) < eps: return a
    t = dot(ab, ap) / mod2(ab)
    return a + ab * t

def line_circle_intersection(a, b, o, r):
    # line ab, circle center o radius r
    ret = []
    t = project_on_line(o, a, b)
    ot = t - o
    d = mod(ot)
    if d - r > eps:
        return ret
    if abs(d - r) < eps:
        ret.append(t)
        return ret
    lr = math.sqrt(max(0.0, r * r - mod2(ot)))
    dir_vec = unit(b - a) if mod(b - a) > eps else Point(0, 0)
    ret.append(t + dir_vec * lr)
    ret.append(t - dir_vec * lr)
    return ret

def point_tangent_circle(p, o, r):
    # tangent points from p to circle (o, r)
    ret = []
    po = p - o
    x2 = mod2(po)
    d2 = x2 - r * r
    if d2 < -eps:
        return ret
    if r <= eps:
        ret.append(o)
        ret.append(o)
        return ret
    d2 = max(0.0, d2)
    q1 = o + po * (r * r / x2)
    q2 = po.rot90() * (-r * math.sqrt(d2) / x2)
    ret.append(q1 - q2)
    ret.append(q1 + q2)
    return ret

def on_segment(p, a, b):
    if abs(cross(b - a, p - a)) > eps:
        return False
    if p.x < min(a.x, b.x) - eps or p.x > max(a.x, b.x) + eps:
        return False
    if p.y < min(a.y, b.y) - eps or p.y > max(a.y, b.y) + eps:
        return False
    return True

def dist_to_line(p, a, b):
    return mod(p - project_on_line(p, a, b))

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    out_lines = []
    while True:
        try:
            px = float(next(it))
            py = float(next(it))
            vp = float(next(it))
            sx = float(next(it))
            sy = float(next(it))
            vs = float(next(it))
            r = float(next(it))
        except StopIteration:
            break

        p = Point(px, py)
        s = Point(sx, sy)

        len_or = mod(p)
        if len_or < eps:
            sita = 0.0
        else:
            sita = math.acos(max(-1.0, min(1.0, p.x / len_or)))
            if p.y < 0:
                sita = -sita

        def check(t):
            # position of p at time t
            angle = sita + t * vp / len_or if len_or > eps else sita
            e = Point(len_or * math.cos(angle), len_or * math.sin(angle))

            ccp = line_circle_intersection(s, e, Point(0, 0), r)

            direct_dist = mod(e - s)
            if len(ccp) != 2 or (not on_segment(ccp[0], s, e) and not on_segment(ccp[1], s, e)):
                return vs * t > direct_dist

            # Path goes through circle, need tangents
            ttp1 = point_tangent_circle(s, Point(0, 0), r)
            if len(ttp1) < 2: return False # Should not happen if s is outside
            # Choose tangent point closer to line se (or rather, the one on the correct side)
            # The C++ code sorts by distance to line se
            if dist_to_line(ttp1[0], s, e) > dist_to_line(ttp1[1], s, e):
                ttp1[0], ttp1[1] = ttp1[1], ttp1[0]
            l1 = mod(ttp1[0] - s)

            ttp2 = point_tangent_circle(e, Point(0, 0), r)
            if len(ttp2) < 2: return False
            if dist_to_line(ttp2[0], s, e) > dist_to_line(ttp2[1], s, e):
                ttp2[0], ttp2[1] = ttp2[1], ttp2[0]
            l2 = mod(ttp2[0] - e)

            # Angle between tangent points vectors from origin
            alph = angle_between(ttp1[0], ttp2[0])

            path_len = l1 + l2 + alph * r
            return path_len < vs * t

        left = 0.0
        right = 1e10
        for _ in range(100): # sufficient for 1e-12 precision on 1e10 range
            mid = (left + right) * 0.5
            if check(mid):
                right = mid
            else:
                left = mid

        out_lines.append(f"{left:.9f}")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
