	//cout << "|-|alph = " << alph << ", " << VecMod( PtoV(s,ttp1[0]) )   << "," << VecMod( PtoV(e,ttp2[0]) ) << endl;
	return VecMod( PtoV(s,ttp1[0]) )
		+  VecMod( PtoV(e,ttp2[0]) )
		+ alph * r < vs*t;
